    });
    return {
      theme: value && themeIds.includes(value.theme) ? value.theme : DEFAULT_SETTINGS.theme,
      inputMode: value && modeIds.includes(value.inputMode) ? value.inputMode : DEFAULT_SETTINGS.inputMode,
    };
  };

